  let y = m;
  for (let d = distance; d > 0; d--) {
    const previous = trace[d - 1];
    const k = x - y;
    const i = (k + d) / 2;
    const insertion = i === 0 || (i < d && previous[i - 1] < previous[i]);
    const previousX = previous[insertion ? i : i - 1];
    const previousY = previousX - (insertion ? k + 1 : k - 1);
    while (x > previousX && y > previousY) {
      edits.push({ op: 'equal', line: a[--x] });
      y--;
    }
    if (insertion) {
      edits.push({ op: 'insert', line: b[previousY] });
    } else {
      edits.push({ op: 'delete', line: a[previousX] });
