    x = previousX;
    y = previousY;
  }
  while (x > 0) {
    edits.push({ op: 'equal', line: a[--x] });
  }
  edits.reverse();

  // A shortest path can interleave edits; stably put deletes first per region.
  const inserts = [];
  for (let i = 0; i < edits.length;) {
    if (edits[i].op === 'equal') {
      i++;
      continue;
    }
    let write = i;
    while (i < edits.length && edits[i].op !== 'equal') {
      const edit = edits[i++];
      if (edit.op === 'insert') inserts.push(edit);
      else edits[write++] = edit;
    }
    for (const insert of inserts) edits[write++] = insert;
    inserts.length = 0;
  }
  return edits;
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  const edits = diffLines(a, b);
  const ranges = [];
  for (let i = 0; i < edits.length; i++) {
    if (edits[i].op === 'equal') continue;
    const start = Math.max(0, i - context);
    const end = Math.min(edits.length, i + context + 1);
    const previous = ranges[ranges.length - 1];
    if (previous && start <= previous.end) {
      previous.end = end;
    } else {
      ranges.push({ start, end });
    }
  }

  const hunks = [];
  let oldPosition = 0;
  let newPosition = 0;
  let position = 0;
  for (const { start, end } of ranges) {
    // Everything outside the ranges is unchanged.
    oldPosition += start - position;
    newPosition += start - position;
    let oldLines = 0;
    let newLines = 0;
    const lines = [];
    for (position = start; position < end; position++) {
      const { op, line } = edits[position];
      if (op !== 'insert') oldLines++;
      if (op !== 'delete') newLines++;
      lines.push((op === 'equal' ? ' ' : op === 'delete' ? '-' : '+') + line);
    }
    hunks.push({
      oldStart: oldPosition + (oldLines === 0 ? 0 : 1),
      oldLines,
      newStart: newPosition + (newLines === 0 ? 0 : 1),
      newLines,
      lines,
    });
    oldPosition += oldLines;
    newPosition += newLines;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  if (!Array.isArray(hunks)) invalidHunk(0);
  const result = [];
  let position = 0;
  for (let index = 0; index < hunks.length; index++) {
    const hunk = hunks[index];
    if (!hunk || typeof hunk !== 'object') invalidHunk(index);
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (![oldStart, oldLines, newStart, newLines].every(
      value => Number.isSafeInteger(value) && value >= 0,
    ) || !Array.isArray(lines)) invalidHunk(index);

    const oldIndex = oldStart - (oldLines === 0 ? 0 : 1);
    const newIndex = newStart - (newLines === 0 ? 0 : 1);
    if (oldIndex < position || oldIndex > a.length ||
        oldLines > a.length - oldIndex ||
        newIndex !== result.length + oldIndex - position) {
      invalidHunk(index);
    }
    while (position < oldIndex) result.push(a[position++]);
    const oldEnd = oldIndex + oldLines;
    const newBeginning = result.length;
    for (const line of lines) {
      if (typeof line !== 'string' || line.length === 0) invalidHunk(index);
      const prefix = line[0];
      const text = line.slice(1);
      if (prefix === ' ' || prefix === '-') {
        if (position >= oldEnd || a[position] !== text) invalidHunk(index);
        position++;
        if (prefix === ' ') result.push(text);
      } else if (prefix === '+') {
        result.push(text);
      } else {
        invalidHunk(index);
      }
    }
    if (position !== oldEnd || result.length - newBeginning !== newLines) {
      invalidHunk(index);
    }
  }
  while (position < a.length) result.push(a[position++]);
  return result;
}

function invalidHunk(index) {
  throw new Error(`hunk ${index} does not apply`);
}

module.exports = { diffLines, unifiedHunks, applyHunks };

