'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Array(b.length + 1).fill(0);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const above = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(above, row[j - 1]);
      diagonal = above;
    }
  }
  return row[b.length];
}

function verify(a, b) {
  Object.freeze(a);
  Object.freeze(b);
  const edits = diffLines(a, b);
  assert.deepEqual(edits.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(edits.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(edits.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  assert.deepEqual(diffLines(a, b), edits);
  let inserted = false;
  for (const { op } of edits) {
    if (op === 'equal') inserted = false;
    else if (op === 'insert') inserted = true;
    else {
      assert.equal(op, 'delete');
      assert.equal(inserted, false);
    }
  }
  for (const context of [0, 1, 2, 3]) {
    const hunks = unifiedHunks(a, b, { context });
    for (const hunk of hunks) {
      Object.freeze(hunk.lines);
      Object.freeze(hunk);
    }
    Object.freeze(hunks);
    assert.deepEqual(applyHunks(a, hunks), b);
  }
}

test('exhaustive minimality, repetitive lines, ordering, frozen inputs and roundtrips', () => {
  const arrays = [[]];
  for (let length = 1; length <= 5; length++) {
    for (let bits = 0; bits < 2 ** length; bits++) {
      arrays.push(Array.from({ length }, (_, i) => (bits & (1 << i)) ? 'x' : ''));
    }
  }
  for (const a of arrays) for (const b of arrays) verify(a, b);
});

test('deterministic varied-line fuzz including prefix-like text', () => {
  let state = 20261001;
  function random(n) {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state % n;
  }
  const alphabet = ['', ' ', '-', '+', 'same', 'different'];
  for (let i = 0; i < 500; i++) {
    const a = Array.from({ length: random(20) }, () => alphabet[random(alphabet.length)]);
    const b = Array.from({ length: random(20) }, () => alphabet[random(alphabet.length)]);
    verify(a, b);
  }
});

test('zero-line coordinates at top, middle and end', () => {
  for (let index = 0; index <= 3; index++) {
    const a = ['a', 'b', 'c'];
    const b = a.slice();
    b.splice(index, 0, '+');
    assert.deepEqual(unifiedHunks(a, b, { context: 0 }), [{
      oldStart: index, oldLines: 0, newStart: index + 1, newLines: 1, lines: ['++'],
    }]);
    assert.deepEqual(unifiedHunks(b, a, { context: 0 }), [{
      oldStart: index + 1, oldLines: 1, newStart: index, newLines: 0, lines: ['-+'],
    }]);
  }
  assert.deepEqual(unifiedHunks([], [], { context: 0 }), []);
  assert.deepEqual(unifiedHunks([], ['']), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+'] }]);
  assert.deepEqual(unifiedHunks([''], []), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-'] }]);
});

test('context boundaries merge touching windows without duplicate lines', () => {
  const a = Array.from({ length: 10 }, (_, i) => String(i));
  const touching = a.slice();
  touching[2] = 'A';
  touching[5] = 'B';
  assert.deepEqual(unifiedHunks(a, touching, { context: 1 }), [{
    oldStart: 2, oldLines: 6, newStart: 2, newLines: 6,
    lines: [' 1', '-2', '+A', ' 3', ' 4', '-5', '+B', ' 6'],
  }]);
  const separated = a.slice();
  separated[2] = 'A';
  separated[6] = 'B';
  assert.deepEqual(unifiedHunks(a, separated, { context: 1 }), [
    { oldStart: 2, oldLines: 3, newStart: 2, newLines: 3, lines: [' 1', '-2', '+A', ' 3'] },
    { oldStart: 6, oldLines: 3, newStart: 6, newLines: 3, lines: [' 5', '-6', '+B', ' 7'] },
  ]);
  assert.deepEqual(unifiedHunks(a, separated), [{
    oldStart: 1, oldLines: 10, newStart: 1, newLines: 10,
    lines: [' 0', ' 1', '-2', '+A', ' 3', ' 4', ' 5', '-6', '+B', ' 7', ' 8', ' 9'],
  }]);
});

test('application preserves gaps and tracks offsets in original coordinates', () => {
  const a = Object.freeze(['a', 'b', 'c', 'd', 'e']);
  const hunks = [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+first'] },
    { oldStart: 2, oldLines: 1, newStart: 2, newLines: 0, lines: ['-b'] },
    { oldStart: 4, oldLines: 1, newStart: 4, newLines: 2, lines: ['-d', '+D', '+extra'] },
  ];
  assert.deepEqual(applyHunks(a, hunks), ['first', 'a', 'c', 'D', 'extra', 'e']);
  const copy = applyHunks(a, []);
  assert.deepEqual(copy, a);
  assert.notEqual(copy, a);
});

test('malformed, mismatched, unordered and overlapping hunks report the index', () => {
  const a = ['a', 'b', 'c'];
  const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const invalid = [
    null, {}, { ...valid, lines: null }, { ...valid, lines: [''] },
    { ...valid, lines: [0] }, { ...valid, lines: ['?b'] },
    { ...valid, lines: ['-wrong', '+B'] }, { ...valid, lines: [' wrong'] },
    { ...valid, oldStart: 0 }, { ...valid, oldStart: 5 },
    { ...valid, oldStart: 1.5 }, { ...valid, oldStart: NaN },
    { ...valid, oldLines: -1 }, { ...valid, oldLines: 4 },
    { ...valid, oldLines: 0 }, { ...valid, newLines: 0 },
    { ...valid, newStart: 0 }, { ...valid, newStart: 3 },
    { ...valid, newLines: Infinity }, { ...valid, newLines: '1' },
    { ...valid, lines: ['-b', '-c', '+B'] },
  ];
  for (const hunk of invalid) assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, null), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { ...valid, oldStart: 1, newStart: 1 }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { oldStart: 3, oldLines: 1, newStart: 3, newLines: 1, lines: [' wrong'] }]), /hunk 1 does not apply/);
});

test('small edits on 20,000 unique and repetitive lines stay well below a second', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? 'same' : `line ${i}`);
    const b = a.slice();
    b.splice(50, 0, 'inserted');
    b[10000] = 'replacement';
    b.splice(19000, 1);
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const result = applyHunks(a, hunks);
    const elapsed = performance.now() - start;
    assert.equal(script.filter(e => e.op !== 'equal').length, 4);
    assert.deepEqual(result, b);
    assert.ok(elapsed < 750, `20,000-line workflow took ${elapsed.toFixed(2)}ms`);
    console.log(`20,000 ${repetitive ? 'repetitive' : 'unique'} lines: ${elapsed.toFixed(2)}ms`);
  }
});

