    const frontier = new Int32Array(distance + 1);
    const previous = trace[distance - 1];
    trace.push(frontier);
    for (let i = 0; i <= distance; i++) {
      const k = 2 * i - distance;
      let x;
      if (distance === 0) {
        x = 0;
      } else if (i === 0 || (i < distance && previous[i - 1] < previous[i])) {
        x = previous[i];
      } else {
        x = previous[i - 1] + 1;
