    { ...valid, newStart: 0 }, { ...valid, newStart: 3 },
    { ...valid, newLines: Infinity }, { ...valid, newLines: '1' },
    { ...valid, lines: ['-b', '-c', '+B'] },
  ];
  for (const hunk of invalid) assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, null), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { ...valid, oldStart: 1, newStart: 1 }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { oldStart: 3, oldLines: 1, newStart: 3, newLines: 1, lines: [' wrong'] }]), /hunk 1 does not apply/);
});

