test('20,000-line empty-side scripts and patches avoid unnecessary search', () => {
  const lines = Object.freeze(Array.from({ length: 20000 }, (_, i) => String(i)));
  for (const [a, b, op] of [[[], lines, 'insert'], [lines, [], 'delete']]) {
    const start = performance.now();
    const edits = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const result = applyHunks(a, hunks);
